<template><view v-if="route" class="page"><view class="banner"><image :src="route.pano" mode="aspectFill"/><view class="mask"/><view class="info"><text class="title">{{route.name}}</text><text>{{route.spirit}} · {{route.from}} 至 {{route.to}}</text><text class="level">Lv.4 运河领航者</text><view class="bp"><view :style="{width:route.pct+'%'}"/></view><text>{{route.distance}} / {{route.total}} km（{{route.pct}}%）</text></view></view><view class="data card"><view><b class="orange">312</b><text>消耗卡路里</text></view><view><b>{{route.distance}}</b><text>总里程 km</text></view><view><b>未解锁</b><text>{{route.medalName}}</text></view></view><view class="position"><b>当前位置</b><text>{{route.from}} → {{route.current}}，继续向下一站前进</text></view><view class="section-title">路跑线路图 · 已解锁 6/19 站</view><view class="hint">沿蜿蜒古道虚拟奔跑，抵达每一站自动解锁当地历史典故</view><view class="scroll"><image src="/static/running/scroll_canal.jpg" mode="aspectFill"/><view class="road"/><view class="node n1">起　北京</view><view class="node n2">✓ 德州</view><view class="node n3">● 聊城</view><view class="node n4 off">○ 济宁</view><view class="node n5 off">终　杭州</view></view><view class="actions"><button class="ghost">设为计入线路</button><button class="pill-btn" @tap="start">开始跑步（计入此线路）</button></view></view></template>
<script>import {routes} from '../../common/mock.js';export default{data:()=>({route:routes[0]}),onLoad(q){this.route=routes.find(r=>r.id===q.id)||routes[0]},methods:{start(){uni.navigateTo({url:'/pages/running/running?id='+this.route.id})}}}</script>
<style scoped>.banner{height:360rpx;position:relative;color:#fff}.banner>image,.mask{position:absolute;width:100%;height:100%}.mask{background:linear-gradient(180deg,rgba(0,0,0,.1),rgba(0,0,0,.72))}.info{position:absolute;left:40rpx;right:40rpx;bottom:38rpx}.info text{display:block;font-size:25rpx}.title{font-size:52rpx!important;font-weight:700}.level{display:inline-block!important;border:1rpx solid #fff;border-radius:99rpx;padding:4rpx 18rpx;margin-top:14rpx}.bp{height:14rpx;background:rgba(255,255,255,.3);border-radius:99rpx;margin-top:18rpx}.bp view{height:100%;background:#fff}.data{display:flex;margin-top:-28rpx;position:relative}.data>view{flex:1;text-align:center}.data b,.data text{display:block}.data b{font-size:38rpx}.data text{font-size:21rpx;color:#999;margin-top:7rpx}.orange{color:#ff6a00}.position{margin:20rpx 24rpx;display:flex;align-items:center}.position b{background:#ff6a00;color:#fff;padding:5rpx 12rpx;border-radius:7rpx;font-size:22rpx}.position text{font-size:24rpx;color:#666;margin-left:14rpx}.hint{text-align:center;color:#999;font-size:22rpx;margin:0 28rpx 16rpx}.scroll{height:620rpx;margin:0 24rpx;border-radius:20rpx;overflow:hidden;position:relative}.scroll>image{width:100%;height:100%}.road{position:absolute;left:48%;top:5%;width:18rpx;height:90%;border-radius:99rpx;background:linear-gradient(#ff8a3d 0 45%,rgba(255,255,255,.75) 45%);transform:rotate(8deg)}.node{position:absolute;background:#fff;color:#333;border:2rpx solid #ff8a3d;border-radius:99rpx;padding:8rpx 18rpx;font-weight:700}.n1{bottom:6%;left:24%}.n2{bottom:33%;right:16%}.n3{bottom:49%;left:18%;color:#ff6a00}.n4{top:25%;right:17%}.n5{top:5%;left:24%}.off{opacity:.68;border-color:#aaa;color:#888}.actions{display:flex;gap:16rpx;padding:24rpx}.actions button{font-size:27rpx;line-height:88rpx}.actions .pill-btn{flex:1}.ghost{background:#fff0e6;color:#e85d00;border-radius:99rpx}</style>
